Table A INVENTARIO
Table B EMPRESAS
Table C FAMILIA
Table D INVENTARIO_ENDERECO
Table E INVENTARIO_STATUS

SELECT
   A.CODIGO,
   A.DESCR,
   A.EMPRESA,
   B.DESCR AS DEMPRESA,
   A.FAMILIA,
   C.DESCR AS DFAMILIA,
   TO_CLOB(
      LISTAGG(TRIM(D.ENDERECO), ', ')
      WITHIN GROUP (ORDER BY D.ENDERECO)
   ) AS ENDERECO,
   A.DTPREV,
   A.STATUS,
   E.DESCR AS DSTATUS,
   A.USUARIO,
   A.NRECNO,
   A.USRESP
FROM
   <A>
   LEFT JOIN <D> ON D.CODIGO = A.CODIGO,
   <B>, <C>, <E>
WHERE
   A.EMPRESA = B.CODIGO AND
   A.FAMILIA = C.CODIGO AND
   A.STATUS  = E.CODIGO
GROUP BY
   A.CODIGO,
   A.DESCR,
   A.EMPRESA,
   B.DESCR,
   A.FAMILIA,
   C.DESCR,
   A.DTPREV,
   A.STATUS,
   E.DESCR,
   A.USUARIO,
   A.NRECNO,
   A.USRESP
ORDER BY
   A.CODIGO DESC
